//! Required real first-user/native/config producers on both migrated engines.
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
use serde_json::{json,Value};use sqlx::{AnyPool,Connection,Column,Row};use tower::ServiceExt;
use std::{path::{Path,PathBuf},collections::BTreeMap,io::Read};use sha2::{Digest,Sha256};
const JWT:&str="owned-password-fixture-secret";const PASSWORD:&str="owned-fixture-password-not-a-real-account";
fn workspace()->PathBuf{PathBuf::from(std::env::var("STARLANE_PASSKEY_WORKSPACE").expect("required owned TOTP workspace"))}
async fn pool(url:&str,schema:&str)->AnyPool{sqlx::any::install_default_drivers();let engine=crate::db::DatabaseEngine::from_url(url).unwrap();let schema=schema.to_owned();sqlx::any::AnyPoolOptions::new().max_connections(3).after_connect(move|c,_|{let schema=schema.clone();Box::pin(async move{match engine{crate::db::DatabaseEngine::Postgres=>{sqlx::query(&format!("SET search_path TO {schema}")).execute(c).await?;},crate::db::DatabaseEngine::Sqlite=>{sqlx::query("PRAGMA foreign_keys=ON").execute(&mut*c).await?;sqlx::query("PRAGMA busy_timeout=5000").execute(c).await?;}}Ok(())})}).connect(url).await.unwrap()}
fn state(db:AnyPool,root:&Path)->crate::AppState{crate::AppState{db,jwt_secret:JWT.into(),base_url:"https://passkey.owned.invalid".into(),search_index:crate::search::SearchIndex::new(root.join("search_index")).unwrap(),oauth_cache:crate::auth::routes::OAuthStateCache::new(),ws_rooms:crate::sync::WsRooms::default()}}

async fn call(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->(StatusCode,Value){println!("PASSKEY_STEP {method} {uri}");let mut q=Request::builder().method(method).uri(uri).header("Content-Type","application/json");if let Some(t)=token{q=q.header("Authorization",format!("Bearer {t}"));}let mut req=q.body(Body::from(body.to_string())).unwrap();req.extensions_mut().insert(axum::extract::ConnectInfo("127.0.0.1:43123".parse::<std::net::SocketAddr>().unwrap()));let r=crate::api_routes().with_state(s.clone()).oneshot(req).await.unwrap();let code=r.status();let bytes=to_bytes(r.into_body(),4*1024*1024).await.unwrap();(code,if bytes.is_empty(){Value::Null}else{serde_json::from_slice(&bytes).unwrap_or(json!({"non_json":true}))})}
async fn ok(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->Value{let(code,v)=call(s,token,method,uri,body).await;assert!(code.is_success(),"actual {method} {uri} status={code}; response suppressed to protect credentials");v}
fn access(v:&Value)->&str{v["access_token"].as_str().unwrap()}fn refresh(v:&Value)->&str{v["refresh_token"].as_str().unwrap()}fn sid(v:&Value)->String{crate::auth::jwt::validate_token(access(v),JWT,crate::auth::jwt::TokenType::Access).unwrap().sid}
async fn snapshot(db:&AnyPool,tables:&[&str])->BTreeMap<String,Vec<Value>>{let mut out=BTreeMap::new();for table in tables{let mut values=Vec::new();for row in sqlx::query(&format!("SELECT * FROM {table}")).fetch_all(db).await.unwrap(){let mut cells=BTreeMap::new();for col in row.columns(){let n=col.name();let v=if let Ok(v)=row.try_get::<Option<String>,_>(n){v.map(|v|json!(["text",v])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<i64>,_>(n){v.map(|v|json!(["integer",v.to_string()])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<Vec<u8>>,_>(n){v.map(|v|json!(["blob",hex::encode(v)])).unwrap_or(json!(["null"]))}else{panic!("unsupported cell {table}.{n}")};cells.insert(n.to_string(),v);}values.push(serde_json::to_value(cells).unwrap());}values.sort_by_cached_key(Value::to_string);out.insert(table.to_string(),values);}out}
fn login_body(email:&str,password:&str)->Value{json!({"email":email,"password":password,"device_name":"Owned browser","session_kind":"browser","client_platform":"web"})}
fn bytes(root:&Path)->BTreeMap<String,String>{fn walk(root:&Path,p:&Path,out:&mut BTreeMap<String,String>){let m=std::fs::symlink_metadata(p).unwrap();assert!(!m.file_type().is_symlink());if m.is_dir(){for e in std::fs::read_dir(p).unwrap(){walk(root,&e.unwrap().path(),out);}}else{assert!(m.is_file());let mut f=std::fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}out.insert(p.strip_prefix(root).unwrap().to_string_lossy().into(),hex::encode(h.finalize()));}}let mut out=BTreeMap::new();for n in["spaces",".storage-journal",".publication-journal",".canonical-rewrite-journal",".move-relocation-journal"]{let p=root.join(n);if p.exists(){walk(root,&p,&mut out);}}out}




const EMAIL:&str="passkey-owner@owned.invalid";
const DOMAIN:&[&str]=&["users","sessions","spaces","space_members","documents","document_drafts","storage_journal_receipts","system_config","audit_log","passkeys","passkey_challenges"];
const STABLE:&[&str]=&["users","spaces","space_members","documents","document_drafts","storage_journal_receipts","system_config","passkeys"];
fn audited_lease(before:&BTreeMap<String,Vec<Value>>,after:&BTreeMap<String,Vec<Value>>,token:&str,start:chrono::DateTime<chrono::Utc>,end:chrono::DateTime<chrono::Utc>){
 let claims=crate::auth::jwt::validate_token(token,JWT,crate::auth::jwt::TokenType::Access).unwrap();let mut expected=before.clone();
 let source=expected.get_mut("sessions").unwrap().iter_mut().find(|r|r["id"][1]==claims.sid).expect("actual source session");let actual=after["sessions"].iter().find(|r|r["id"][1]==claims.sid).expect("actual same session");assert_eq!(source["user_id"][1],claims.sub);
 let days=crate::auth::routes::session_inactivity_days(source["session_kind"][1].as_str().unwrap());
 for (key,delta) in [("last_seen_at",chrono::Duration::zero()),("expires_at",chrono::Duration::days(days))]{let value=&actual[key];assert_eq!(value[0],"text");let stamp=chrono::DateTime::parse_from_rfc3339(value[1].as_str().unwrap()).unwrap().with_timezone(&chrono::Utc);assert!(stamp>=start+delta&&stamp<=end+delta,"actual lease timestamp outside request window");source.as_object_mut().unwrap().insert(key.into(),value.clone());}
 expected.get_mut("sessions").unwrap().sort_by_cached_key(Value::to_string);assert!(&expected==after,"authenticated request changed rows beyond exact current-sid lease and approved operation transition");
}
async fn consume(s:crate::AppState,token:String,id:String,count:std::sync::Arc<std::sync::atomic::AtomicUsize>,barrier:Option<std::sync::Arc<tokio::sync::Barrier>>)->StatusCode{
 let hook:Option<std::pin::Pin<Box<dyn std::future::Future<Output=()>+Send>>>=barrier.map(|b|Box::pin(async move{b.wait().await;})as _);
 crate::auth::routes::PASSKEY_TAKE_COUNT.scope(count,crate::auth::routes::PASSKEY_TAKE_PROGRESS.scope(std::cell::RefCell::new(hook),call(&s,Some(&token),"POST","/auth/passkeys/register/finish",json!({"challenge_id":id,"credential":{}})))).await.0
}
async fn delete_failure(s:&crate::AppState,engine:&str,token:&str,id:&str){
 let before=snapshot(&s.db,DOMAIN).await;let files=bytes(&crate::storage::data_dir());
 if engine=="sqlite"{sqlx::query("CREATE TRIGGER passkey_fail AFTER DELETE ON passkey_challenges BEGIN SELECT RAISE(ABORT,'owned passkey failure'); END").execute(&s.db).await.unwrap();}else{sqlx::query("CREATE FUNCTION passkey_fail_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'owned passkey failure'; END $$").execute(&s.db).await.unwrap();sqlx::query("CREATE TRIGGER passkey_fail AFTER DELETE ON passkey_challenges FOR EACH ROW EXECUTE FUNCTION passkey_fail_fn()").execute(&s.db).await.unwrap();}
 let count=std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));let started=chrono::Utc::now();assert_eq!(consume(s.clone(),token.into(),id.into(),count.clone(),None).await,StatusCode::INTERNAL_SERVER_ERROR);assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst),0);audited_lease(&before,&snapshot(&s.db,DOMAIN).await,token,started,chrono::Utc::now());assert_eq!(files,bytes(&crate::storage::data_dir()));
 if engine=="sqlite"{sqlx::query("DROP TRIGGER passkey_fail").execute(&s.db).await.unwrap();}else{sqlx::query("DROP TRIGGER passkey_fail ON passkey_challenges").execute(&s.db).await.unwrap();sqlx::query("DROP FUNCTION passkey_fail_fn()").execute(&s.db).await.unwrap();}
 println!("PASSKEY_REAL_DELETE_ROLLBACK_PASS");
}
async fn run(engine:&str,kind:&str){
 let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));
 let url=if engine=="postgres"{std::env::var("STARLANE_PASSKEY_PG_URL").expect("required owned PG URL")}else{format!("sqlite://{}?mode=rwc",root.join("starlane-notes.db").display())};
 std::fs::create_dir_all(&root).unwrap();
 let schema=if engine=="postgres"{sqlx::any::install_default_drivers();let n=format!("passkey_{}",uuid::Uuid::new_v4().simple());let mut c=sqlx::AnyConnection::connect(&url).await.unwrap();sqlx::query(&format!("CREATE SCHEMA {n}")).execute(&mut c).await.unwrap();c.close().await.unwrap();n}else{String::new()};
 let db=pool(&url,&schema).await;crate::db::migrate_selected(&db,crate::db::DatabaseEngine::from_url(&url).unwrap()).await.unwrap();let s=state(db,&root);
 let signup=ok(&s,None,"POST","/auth/register",json!({"email":EMAIL,"display_name":"Passkey owner","password":PASSWORD})).await;
 let mut login=ok(&s,None,"POST","/auth/login",login_body(EMAIL,PASSWORD)).await;assert_eq!(signup["user"]["id"],login["user"]["id"]);
 let uid=login["user"]["id"].as_str().unwrap();let space:String=sqlx::query_scalar("SELECT id FROM spaces WHERE created_by=$1").bind(uid).fetch_one(&s.db).await.unwrap();
 let page=ok(&s,Some(access(&login)),"POST",&format!("/spaces/{space}/documents"),json!({"source_id":"passkey-page","title":"Passkey page","content":"EXACT_PASSKEY_PAGE Ω","property_values":[]})).await;
 ok(&s,Some(access(&login)),"POST",&format!("/spaces/{space}/documents/passkey-page/drafts/{}/publish",page["draft_id"].as_str().unwrap()),json!({})).await;
 let member=if kind=="owner"{ok(&s,Some(access(&login)),"POST","/admin/config",json!({"key":"allow_public_signups","value":"true"})).await;ok(&s,None,"POST","/auth/register",json!({"email":"passkey-member@owned.invalid","display_name":"Member","password":PASSWORD})).await;Some(ok(&s,None,"POST","/auth/login",login_body("passkey-member@owned.invalid",PASSWORD)).await)}else{None};
 let before=snapshot(&s.db,STABLE).await;let files=bytes(&root);
 let challenge=if kind=="options"{
 for email in [EMAIL," PASSKEY-OWNER@OWNED.INVALID "]{let v=ok(&s,None,"POST","/auth/sign-in-options",json!({"email":email})).await;assert_eq!(v,json!({"password_available":true,"passkey_available":false}));}
 for email in ["","missing@owned.invalid"]{let v=ok(&s,None,"POST","/auth/sign-in-options",json!({"email":email})).await;assert_eq!(v,json!({"password_available":false,"passkey_available":false}));}Value::Null
 }else{
 assert_eq!(ok(&s,Some(access(&login)),"GET","/auth/passkeys",Value::Null).await,json!([]));
 let v=ok(&s,Some(access(&login)),"POST","/auth/passkeys/register/start",json!({"name":"Owned challenge"})).await;
 let id=v["challenge_id"].as_str().unwrap();uuid::Uuid::parse_str(id).unwrap();assert!(v["public_key"]["publicKey"]["challenge"].is_string(),"actual library challenge absent");
 let row:(String,String,String,String)=sqlx::query_as("SELECT user_id,email,kind,state_json FROM passkey_challenges WHERE id=$1").bind(id).fetch_one(&s.db).await.unwrap();assert_eq!(row.0,uid);assert_eq!(row.1,EMAIL);assert_eq!(row.2,"registration");let _:webauthn_rs::prelude::PasskeyRegistration=serde_json::from_str(&row.3).unwrap();
 if kind=="owner"||kind=="kind"{let held=snapshot(&s.db,DOMAIN).await;assert_eq!(held["passkey_challenges"].len(),1);let started=chrono::Utc::now();let status=if kind=="owner"{call(&s,Some(access(member.as_ref().unwrap())),"POST","/auth/passkeys/register/finish",json!({"challenge_id":id,"credential":{}})).await.0}else{call(&s,None,"POST","/auth/passkeys/login/finish",json!({"challenge_id":id,"credential":{}})).await.0};assert_eq!(status,if kind=="owner"{StatusCode::UNAUTHORIZED}else{StatusCode::BAD_REQUEST});if kind=="owner"{assert_eq!(snapshot(&s.db,&["passkey_challenges"]).await, BTreeMap::from([("passkey_challenges".to_owned(),held["passkey_challenges"].clone())]));audited_lease(&held,&snapshot(&s.db,DOMAIN).await,access(member.as_ref().unwrap()),started,chrono::Utc::now());}else{let mut expected=held.clone();expected.get_mut("passkey_challenges").unwrap().clear();assert!(expected==snapshot(&s.db,DOMAIN).await,"wrong-kind retirement changed unrelated domain rows");println!("PASSKEY_EXISTING_WRONG_KIND_RETIREMENT_PASS");}}
 if kind=="owner"||kind=="concurrency"||kind=="rollback"{
  if kind=="rollback"{delete_failure(&s,engine,access(&login),id).await;}
  let before=snapshot(&s.db,DOMAIN).await;assert_eq!(before["passkey_challenges"].len(),1);
  let count=std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));let started=chrono::Utc::now();
  if kind=="concurrency"{let b=std::sync::Arc::new(tokio::sync::Barrier::new(2));let (a,b)=tokio::join!(consume(s.clone(),access(&login).into(),id.into(),count.clone(),Some(b.clone())),consume(s.clone(),access(&login).into(),id.into(),count.clone(),Some(b)));assert_eq!(a,StatusCode::BAD_REQUEST);assert_eq!(b,StatusCode::BAD_REQUEST);}else{assert_eq!(consume(s.clone(),access(&login).into(),id.into(),count.clone(),None).await,StatusCode::BAD_REQUEST);}
  assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst),1,"authentic state was acquired by more than one consumer");let mut expected=before;expected.get_mut("passkey_challenges").unwrap().clear();audited_lease(&expected,&snapshot(&s.db,DOMAIN).await,access(&login),started,chrono::Utc::now());println!("PASSKEY_REAL_EXACT_ONE_ACQUISITION_PASS");
 }
 if kind=="expiry"{sqlx::query("UPDATE passkey_challenges SET expires_at=$1 WHERE id=$2").bind((chrono::Utc::now()-chrono::Duration::minutes(1)).to_rfc3339()).bind(id).execute(&s.db).await.unwrap();let mut b=snapshot(&s.db,DOMAIN).await;assert_eq!(b["passkey_challenges"].len(),1);let started=chrono::Utc::now();assert_eq!(call(&s,Some(access(&login)),"POST","/auth/passkeys/register/finish",json!({"challenge_id":id,"credential":{}})).await.0,StatusCode::BAD_REQUEST);b.get_mut("passkey_challenges").unwrap().clear();audited_lease(&b,&snapshot(&s.db,DOMAIN).await,access(&login),started,chrono::Utc::now());let count:i64=sqlx::query_scalar("SELECT COUNT(*) FROM passkey_challenges WHERE id=$1").bind(id).fetch_one(&s.db).await.unwrap();assert_eq!(count,0);println!("PASSKEY_REAL_EXPIRY_REFUSAL_PASS");}
 assert_eq!(call(&s,None,"POST","/auth/passkeys/login/start",json!({"email":EMAIL})).await.0,StatusCode::UNAUTHORIZED);
 let v=if ["expiry","kind","owner","concurrency","rollback"].contains(&kind){ok(&s,Some(access(&login)),"POST","/auth/passkeys/register/start",json!({"name":"After expiry"})).await}else{v};
 let held=snapshot(&s.db,&["passkey_challenges"]).await;assert_eq!(call(&s,None,"POST","/auth/passkeys/register/start",json!({})).await.0,StatusCode::UNAUTHORIZED);assert_eq!(held,snapshot(&s.db,&["passkey_challenges"]).await);
 ok(&s,Some(access(&login)),"POST","/auth/logout",json!({})).await;let denied=snapshot(&s.db,DOMAIN).await;assert_eq!(call(&s,Some(access(&login)),"POST","/auth/passkeys/register/start",json!({})).await.0,StatusCode::UNAUTHORIZED);assert!(denied==snapshot(&s.db,DOMAIN).await,"current session denial changed authoritative state");login=ok(&s,None,"POST","/auth/login",login_body(EMAIL,PASSWORD)).await;println!("PASSKEY_REAL_REVOKED_SESSION_REFUSAL_PASS");v
 };
 assert_eq!(before,snapshot(&s.db,STABLE).await);assert_eq!(files,bytes(&root));let e=json!({"login":login,"space":space,"stable":before,"files":files,"challenge":challenge,"challenges":snapshot(&s.db,&["passkey_challenges"]).await});std::fs::write(workspace().join("expected.json"),e.to_string()).unwrap();s.db.close().await;drop(s);
 let child=std::process::Command::new(std::env::current_exe().unwrap()).args(["postgres_passkey_fixture::fresh_passkey_child","--ignored","--exact","--nocapture"]).env("STARLANE_PASSKEY_CHILD_URL",url).env("STARLANE_PASSKEY_SCHEMA",schema).output().unwrap();assert!(child.status.success(),"{}\n{}",String::from_utf8_lossy(&child.stdout),String::from_utf8_lossy(&child.stderr));println!("PASSKEY_FRESH_CHILD {}",String::from_utf8_lossy(&child.stdout));println!("PASSKEY_REAL_PARENT_PASS {engine} {kind}");
}
macro_rules! case{($n:ident,$e:literal,$k:literal)=>{#[tokio::test]#[ignore="required owned passkey orchestration"]async fn $n(){run($e,$k).await;}};}
case!(required_postgres_options,"postgres","options");case!(required_sqlite_options,"sqlite","options");case!(required_postgres_challenge,"postgres","challenge");case!(required_sqlite_challenge,"sqlite","challenge");
case!(required_postgres_owner,"postgres","owner");case!(required_sqlite_owner,"sqlite","owner");case!(required_postgres_kind,"postgres","kind");case!(required_sqlite_kind,"sqlite","kind");case!(required_postgres_expiry,"postgres","expiry");case!(required_sqlite_expiry,"sqlite","expiry");
case!(required_postgres_concurrency,"postgres","concurrency");case!(required_sqlite_concurrency,"sqlite","concurrency");case!(required_postgres_rollback,"postgres","rollback");case!(required_sqlite_rollback,"sqlite","rollback");
#[tokio::test]#[ignore="only genuine passkey parent launches"]async fn fresh_passkey_child(){
 let url=std::env::var("STARLANE_PASSKEY_CHILD_URL").expect("required child URL");let schema=std::env::var("STARLANE_PASSKEY_SCHEMA").expect("required parent schema");let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));let e:Value=serde_json::from_slice(&std::fs::read(workspace().join("expected.json")).unwrap()).unwrap();let s=state(pool(&url,&schema).await,&root);
 assert_eq!(serde_json::to_value(snapshot(&s.db,STABLE).await).unwrap(),e["stable"]);assert_eq!(serde_json::to_value(snapshot(&s.db,&["passkey_challenges"]).await).unwrap(),e["challenges"]);
 crate::storage::restoration::bootstrap_gate(&root).unwrap();crate::storage::restoration::activate_in(&root,&s.db).await.unwrap();crate::storage::relocation::recover(&s.db).await.unwrap();crate::storage::journal::recover(&s.db).await.unwrap();crate::storage::canonical_rewrite::recover(&s.db).await.unwrap();crate::storage::publication::recover(&s.db).await.unwrap();crate::storage::attachment_upload::recover_in(&root,&s.db).await.unwrap();
 ok(&s,Some(access(&e["login"])),"GET","/auth/me",Value::Null).await;let content=ok(&s,Some(access(&e["login"])),"GET",&format!("/spaces/{}/documents/passkey-page/content",e["space"].as_str().unwrap()),Value::Null).await;assert!(content["content"].as_str().unwrap().contains("EXACT_PASSKEY_PAGE Ω"));
 if let Some(id)=e["challenge"]["challenge_id"].as_str(){let body=json!({"challenge_id":id,"credential":{}});assert_eq!(call(&s,Some(access(&e["login"])),"POST","/auth/passkeys/register/finish",body.clone()).await.0,StatusCode::BAD_REQUEST);assert_eq!(call(&s,Some(access(&e["login"])),"POST","/auth/passkeys/register/finish",body).await.0,StatusCode::BAD_REQUEST);let count:i64=sqlx::query_scalar("SELECT COUNT(*) FROM passkey_challenges WHERE id=$1").bind(id).fetch_one(&s.db).await.unwrap();assert_eq!(count,0);println!("PASSKEY_REAL_MALFORMED_ONE_TIME_REFUSAL_PASS");}
 assert_eq!(serde_json::to_value(snapshot(&s.db,STABLE).await).unwrap(),e["stable"]);assert_eq!(serde_json::to_value(bytes(&root)).unwrap(),e["files"]);s.db.close().await;drop(s);println!("PASSKEY_REAL_FRESH_RESTART_PASS");
}
